def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform separator rows reveal the line color.
    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    if uniform_rows:
        line_color = grid[uniform_rows[0]][0]
    else:
        # Fallback: choose the color occurring in the most uniform rows/columns.
        line_color = max(
            {v for row in grid for v in row},
            key=lambda color: sum(all(x == color for x in grid[r]) for r in range(h))
                            + sum(all(grid[r][c] == color for r in range(h)) for c in range(w))
        )

    selected_rows = {r for r in range(h) if all(x == line_color for x in grid[r])}
    selected_cols = {c for c in range(w) if all(grid[r][c] == line_color for r in range(h))}

    out = [row[:] for row in grid]
    for r in selected_rows:
        out[r] = [2] * w
    for c in selected_cols:
        for r in range(h):
            out[r][c] = 2
    return out
